def migrar_para_perfil_acesso(apps, schema_editor):
    """Preserva o acesso dos usuários existentes ao trocar o esquema de permissões.

    O modelo anterior (perfil ADMINISTRADOR/GESTOR/ESPECIFICO + lista de módulos avulsa)
    dá lugar a is_admin_total + um PerfilAcesso reutilizável. Aqui, antes de remover os
    campos antigos: ADMINISTRADOR vira is_admin_total; GESTOR vira um PerfilAcesso
    compartilhado "Gestor / RH geral"; ESPECIFICO com módulos ganha um PerfilAcesso próprio
    (um por conjunto distinto de módulos, para não perder nenhuma combinação já em uso).
    """
    User = apps.get_model('pesquisas', 'User')
    PerfilAcesso = apps.get_model('pesquisas', 'PerfilAcesso')

    User.objects.filter(perfil='ADMINISTRADOR').update(is_admin_total=True)

    gestores = User.objects.filter(perfil='GESTOR')
    if gestores.exists():
        perfil_gestor, _ = PerfilAcesso.objects.get_or_create(
            nome='Gestor / RH geral',
            defaults={'modulos_permitidos': ['enps', 'desligamentos', 'talentos']},
        )
        gestores.update(perfil_personalizado=perfil_gestor)

    perfis_por_modulos = {}
    especificos = User.objects.filter(perfil='ESPECIFICO').exclude(modulos_permitidos=[])
    for usuario in especificos:
        chave = tuple(sorted(usuario.modulos_permitidos))
        if chave not in perfis_por_modulos:
            sufixo = '' if not perfis_por_modulos else f' {len(perfis_por_modulos) + 1}'
            perfil, _ = PerfilAcesso.objects.get_or_create(
                nome=f'Perfil migrado{sufixo}', defaults={'modulos_permitidos': list(chave)},
            )
            perfis_por_modulos[chave] = perfil
        usuario.perfil_personalizado = perfis_por_modulos[chave]
        usuario.save(update_fields=['perfil_personalizado'])


